// About: version, the app's own licence, who made the data, sound and fonts it is built on, and the licence of every
// open-source package inside it (generated by `npm run notices`, loaded only when this screen opens).
import Constants from "expo-constants";
import { router } from "expo-router";
import { useEffect, useState } from "react";
import { Linking, Pressable, View } from "react-native";
import { Screen } from "@/components/Screen";
import { SectionTitle } from "@/components/Track";
import { TopBar } from "@/components/TopBar";
import { Card, Group, T } from "@/components/ui";
import { t } from "@/i18n";
import { CREDITS, SOURCE_URL } from "@/lib/credits";
import { useKeys } from "@/lib/useKeys";
import { data } from "@/state/AppState";
import { C } from "@/theme";

const leave = () => (router.canGoBack() ? router.back() : router.replace("/settings"));
const open = (url: string) => { Linking.openURL(url).catch(() => undefined); };

interface Notices { packages: { n: string; v: string; l: string; t: number | null }[]; texts: string[] }
let cache: Notices | undefined;
function useNotices(): Notices | null {
  const [n, setN] = useState<Notices | null>(cache ?? null);
  useEffect(() => {
    if (cache) return;
    let live = true;
    void import("../../../assets/data/notices.v1.json").then((m) => {
      cache = m.default ?? m;
      if (live) setN(cache);
    });
    return () => { live = false; };
  }, []);
  return n;
}

function Link({ label, url }: { label: string; url: string }) {
  return (
    <Pressable accessibilityRole="link" accessibilityHint={url} onPress={() => open(url)} hitSlop={6}>
      <T v="bold" size={14} color={C.highlight}>{label} ↗</T>
    </Pressable>
  );
}

export default function About() {
  const notices = useNotices();
  const [openPkg, setOpenPkg] = useState<string | null>(null);
  useKeys((k) => { if (k === "Escape") leave(); });
  const version = Constants.expoConfig?.version ?? "–";

  return (
    <Screen>
      <TopBar onBack={leave} backLabel={t.session.back} />
      <T v="black" size={34} accessibilityRole="header">{t.about.title}</T>

      <Card navy style={{ gap: 8 }}>
        <T v="black" size={22}>Kanjiskole {version}</T>
        <T size={14} color={C.onNavy} style={{ lineHeight: 21 }}>{t.about.own}</T>
        <T size={12} color={C.onNavyMuted}>{t.misc.dataVersion(data.version)}</T>
        <View style={{ flexDirection: "row", gap: 18, marginTop: 4, flexWrap: "wrap" }}>
          <Link label="GPL-3.0" url="https://www.gnu.org/licenses/gpl-3.0.html" />
          <Link label={t.about.source} url={SOURCE_URL} />
        </View>
      </Card>

      <SectionTitle title={t.about.credits} />
      <T size={14} color={C.muted} style={{ lineHeight: 21 }}>{t.about.edrdg}</T>
      <Group>
        {CREDITS.map((c, i) => (
          <View key={c.name} style={{ padding: 16, gap: 6, borderBottomWidth: i < CREDITS.length - 1 ? 1 : 0, borderBottomColor: C.line }}>
            <T v="bold" size={16}>{c.name}</T>
            <T size={13} color={C.muted}>{t.about.roles[c.role]} · {c.by}</T>
            <View style={{ flexDirection: "row", gap: 18, flexWrap: "wrap" }}>
              <Link label={c.licence} url={c.licenceUrl} />
              <Link label={t.about.website} url={c.url} />
            </View>
          </View>
        ))}
      </Group>
      <T size={13} color={C.muted} style={{ lineHeight: 19 }}>{t.about.dataLicence}</T>

      <SectionTitle title={t.about.packages} right={notices ? t.num(notices.packages.length) : undefined} />
      <T size={14} color={C.muted} style={{ lineHeight: 21 }}>{t.about.packagesHelp}</T>
      {notices ? (
        <Group>
          {notices.packages.map((p, i) => {
            const on = openPkg === p.n;
            return (
              <View key={p.n} style={{ borderBottomWidth: i < notices.packages.length - 1 ? 1 : 0, borderBottomColor: C.line }}>
                <Pressable accessibilityRole="button" accessibilityState={{ expanded: on }} onPress={() => setOpenPkg(on ? null : p.n)}
                  style={({ pressed }) => ({ flexDirection: "row", alignItems: "center", gap: 12, paddingHorizontal: 16, minHeight: 52, opacity: pressed ? 0.7 : 1 })}>
                  <T size={15} style={{ flex: 1 }} numberOfLines={1}>{p.n}</T>
                  <T size={13} color={C.faint}>{p.v}</T>
                  <T size={13} color={C.highlight} style={{ minWidth: 64, textAlign: "right" }}>{p.l}</T>
                </Pressable>
                {on ? (
                  <View style={{ paddingHorizontal: 16, paddingBottom: 16 }}>
                    <T size={12} color={C.muted} style={{ lineHeight: 17, fontFamily: "monospace" }} selectable>
                      {p.t === null ? t.about.noText : notices.texts[p.t]}
                    </T>
                  </View>
                ) : null}
              </View>
            );
          })}
        </Group>
      ) : <T size={14} color={C.faint}>…</T>}
    </Screen>
  );
}
